<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { useRoute } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import http from '../api/http';import { useAuthStore } from '../stores/auth';import { dateText,statusText } from '../utils/format';import { assetUrl } from '../utils/url'
const historyPage=ref(1),reassignVisible=ref(false),candidates=ref([]),candidatePage=ref(1),candidateTotal=ref(0),reassignment=reactive({applicationId:null,dueAt:'',reason:''});
const route=useRoute(),auth=useAuthStore(),data=ref(null),loading=ref(false),completionVisible=ref(false),reviewVisible=ref(false),form=reactive({description:'',proofUrl:''}),review=reactive({rating:5,content:''});const order=computed(()=>data.value?.order),isPublisher=computed(()=>auth.user?.id===order.value?.publisherId),isAccepter=computed(()=>auth.user?.id===order.value?.accepterId);async function load(){data.value=await http.get(`/api/orders/${route.params.id}`,{params:{page:historyPage.value,size:10}})}async function action(name,body={}){loading.value=true;try{data.value=await http.post(`/api/orders/${route.params.id}/${name}`,body);ElMessage.success('操作成功');return true}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function upload(option){const fd=new FormData();fd.append('file',option.file);try{const result=await http.post('/api/files/proofs',fd);form.proofUrl=result.url;option.onSuccess(result);ElMessage.success('凭证已上传')}catch(e){option.onError(e)}}async function submit(){loading.value=true;try{await http.post('/api/orders/'+route.params.id+'/completions',form);await load();completionVisible.value=false;ElMessage.success('完成结果已提交')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function reject(){const {value}=await ElMessageBox.prompt('请说明需要补充或修改的内容','驳回结果',{inputType:'textarea',inputValidator:v=>v?.length>2||'请填写原因'});await action('reject',{reason:value})}async function abnormal(){const {value}=await ElMessageBox.prompt('请描述异常或争议','发起异常处理',{inputType:'textarea',inputValidator:v=>v?.length>3||'请填写说明'});try{await http.post(`/api/tasks/${data.value.task.id}/abnormal`,{reasonType:'DISPUTE',description:value});ElMessage.success('已提交管理员处理');load()}catch(e){ElMessage.error(e.message)}}async function submitReview(){const other=isPublisher.value?data.value.accepter:data.value.publisher;try{await http.post('/api/reviews',{businessType:'TASK',businessId:order.value.id,revieweeId:other.id,...review});ElMessage.success('评价已提交');reviewVisible.value=false}catch(e){ElMessage.error(e.message)}}async function cancelTask(){const {value}=await ElMessageBox.prompt('取消会返还奖励积分，并扣减取消发起人5信用。请填写原因','取消待执行任务',{inputValidator:v=>v?.trim().length>1||'请填写原因'});await http.post(`/api/tasks/${data.value.task.id}/cancel`,{reason:value});await load()}
async function loadCandidates(){const result=await http.get(`/api/tasks/${data.value.task.id}/applications`,{params:{page:candidatePage.value,size:10}});candidates.value=result.records.filter(x=>['PENDING','REJECTED'].includes(x.application.status)&&x.application.applicantId!==order.value.accepterId);candidateTotal.value=result.total}
async function openReassign(){await loadCandidates();reassignVisible.value=true}
async function reassign(){if(!reassignment.applicationId||!reassignment.dueAt||!reassignment.reason.trim()){ElMessage.warning('请选择接取者、新期限并填写原因');return}await http.post(`/api/tasks/${data.value.task.id}/reassign`,reassignment);reassignVisible.value=false;await load()}
function progressActive(){if(order.value?.status==='COMPLETED')return 5;if(order.value?.status==='WAIT_ACCEPTANCE')return 3;if(order.value?.status==='IN_PROGRESS')return data.value?.completions?.length?3:2;return 1}
onMounted(load)
</script>
<style scoped>
:deep(.el-steps--vertical){height:auto}
:deep(.el-step.is-vertical){flex-basis:auto!important;min-height:82px}
:deep(.el-step.is-vertical:last-child){min-height:54px}
@media(max-width:720px){.mobile-action-bar{position:fixed;left:0;right:0;bottom:calc(68px + env(safe-area-inset-bottom));z-index:20;margin:0;padding:12px 16px;background:#fff;border-top:1px solid #e5e9e2;box-shadow:0 -6px 20px rgba(31,48,35,.08)}}
</style>
<template><div v-if="data"><div class="page-head"><div><p>任务履约 #{{order?.id||route.params.id}}</p><h1>{{data.task.title}}</h1></div><span class="status-pill">{{data.historical?'已重新分配':statusText(order.status)}}</span></div><div v-if="data.historical" class="surface panel"><h3>历史履约记录（只读）</h3><p class="muted">该订单已重新分配；你仍可查看本人此前提交的全部记录。</p><div v-for="c in data.completions" :key="c.id" class="list-card"><div><el-tag size="small">{{statusText(c.reviewStatus)}}</el-tag><span class="muted" style="margin-left:8px">{{dateText(c.submitTime)}}</span></div><p>{{c.description}}</p><a v-if="c.proofUrl?.endsWith('.pdf')" :href="assetUrl(c.proofUrl)" target="_blank" rel="noopener">查看 PDF 凭证</a><el-image v-else-if="c.proofUrl" :src="assetUrl(c.proofUrl)" fit="cover" style="width:180px;height:120px;border-radius:10px" :preview-src-list="[assetUrl(c.proofUrl)]"/><p v-if="c.rejectReason" style="color:#b54b4b">驳回原因：{{c.rejectReason}}</p></div><el-pagination v-model:current-page="historyPage" :total="data.completionTotal" :page-size="10" layout="prev,pager,next" @current-change="load"/><div v-if="!data.completions.length" class="muted">暂无历史提交记录</div></div><div v-else class="two-col"><section class="surface panel"><h3 class="panel-title">履约进度 · 第{{order.assignmentRound}}轮</h3><p class="muted">约定完成：{{dateText(order.dueAt)}}</p><el-steps direction="vertical" :active="progressActive()" finish-status="success"><el-step title="确认接单" :description="dateText(order.acceptedAt)"/><el-step title="开始执行" :description="dateText(order.startedAt)"/><el-step title="提交成果" :description="data.completions?.length?dateText(data.completions[0].submitTime):'等待接取者提交'"/><el-step title="任务验收" :description="order.status==='WAIT_ACCEPTANCE'?'等待发布者确认':order.status==='COMPLETED'?'验收通过':'尚未进入验收'"/><el-step title="积分结算" :description="dateText(order.completedAt)"/></el-steps><div class="action-row mobile-action-bar" style="margin-top:20px"><el-button v-if="order.status==='WAIT_EXECUTE'" type="danger" plain @click="cancelTask">取消任务</el-button><el-button v-if="isPublisher&&order.status==='ABNORMAL'&&['TIMEOUT','REJECT_LIMIT'].includes(data.task.abnormalReason)" type="primary" @click="openReassign">重新选择接取者</el-button><el-button v-if="isAccepter&&order.status==='WAIT_EXECUTE'" type="primary" :loading="loading" @click="action('start')">开始任务</el-button><el-button v-if="isAccepter&&order.status==='IN_PROGRESS'" type="primary" @click="completionVisible=true">提交完成结果</el-button><template v-if="isPublisher&&order.status==='WAIT_ACCEPTANCE'"><el-button type="success" :loading="loading" @click="action('approve')">验收通过</el-button><el-button type="danger" plain @click="reject">驳回重提</el-button></template><el-button v-if="['IN_PROGRESS','WAIT_ACCEPTANCE'].includes(order.status)" type="warning" plain @click="abnormal">异常处理</el-button><el-button v-if="order.status==='COMPLETED'" @click="reviewVisible=true">评价对方</el-button></div></section><aside class="section-stack"><section class="surface panel"><h3 class="panel-title">任务双方</h3><p><strong>发布者：</strong>{{data.publisher.nickname}} <span class="muted">信用 {{data.publisher.creditScore}}</span></p><p><strong>接取者：</strong>{{data.accepter.nickname}} <span class="muted">信用 {{data.accepter.creditScore}}</span></p><p><strong>奖励：</strong><span class="points">{{data.task.rewardPoints}}</span> 积分</p></section><section class="surface panel"><h3 class="panel-title">完成记录</h3><div v-for="c in data.completions" :key="c.id" class="list-card" style="background:#f5f7f3"><div><el-tag size="small">{{statusText(c.reviewStatus)}}</el-tag><span class="muted" style="margin-left:8px">{{dateText(c.submitTime)}}</span></div><p class="muted">第{{c.assignmentRound}}轮 · 提交人 #{{c.submitterId||'历史记录'}}</p><p>{{c.description}}</p><a v-if="c.proofUrl?.endsWith('.pdf')" :href="assetUrl(c.proofUrl)" target="_blank" rel="noopener">查看PDF凭证</a><el-image v-else-if="c.proofUrl" :src="assetUrl(c.proofUrl)" fit="cover" style="width:100%;height:150px;border-radius:10px" :preview-src-list="[assetUrl(c.proofUrl)]"/><p v-if="c.rejectReason" style="color:#b54b4b">驳回原因：{{c.rejectReason}}</p></div><el-pagination v-model:current-page="historyPage" :total="data.completionTotal" :page-size="10" layout="prev,pager,next" @current-change="load"/><div v-if="!data.completions.length" class="muted">暂无提交记录</div></section></aside></div><el-dialog v-model="reassignVisible" title="重新选择接取者" width="520"><el-form label-position="top"><el-form-item label="原未选中申请者"><el-select v-model="reassignment.applicationId" class="full"><el-option v-for="item in candidates" :key="item.application.id" :value="item.application.id" :label="item.applicant.nickname+' · 信用'+item.applicant.creditScore"/></el-select><el-pagination v-model:current-page="candidatePage" :total="candidateTotal" :page-size="10" layout="prev,pager,next" @current-change="loadCandidates"/></el-form-item><el-form-item label="新的完成期限"><el-date-picker v-model="reassignment.dueAt" type="datetime" value-format="YYYY-MM-DDTHH:mm:ss"/></el-form-item><el-form-item label="重新分配原因"><el-input v-model="reassignment.reason" type="textarea" maxlength="255"/></el-form-item></el-form><template #footer><el-button @click="reassignVisible=false">取消</el-button><el-button type="primary" @click="reassign">确认重新分配</el-button></template></el-dialog><el-dialog v-model="completionVisible" title="提交完成结果" width="520"><el-form label-position="top"><el-form-item label="完成说明"><el-input v-model="form.description" type="textarea" :rows="4"/></el-form-item><el-form-item label="完成凭证（JPG/PNG/PDF，最多10MB）"><el-upload :http-request="upload" :show-file-list="true" :limit="1" accept=".jpg,.jpeg,.png,.pdf"><el-button>选择并上传凭证</el-button></el-upload><a v-if="form.proofUrl?.endsWith('.pdf')" :href="assetUrl(form.proofUrl)" target="_blank" rel="noopener">查看PDF凭证</a><el-image v-else-if="form.proofUrl" :src="assetUrl(form.proofUrl)" style="width:120px;height:90px;margin-top:10px;border-radius:8px" fit="cover"/></el-form-item></el-form><template #footer><el-button @click="completionVisible=false">取消</el-button><el-button type="primary" :loading="loading" @click="submit">提交验收</el-button></template></el-dialog><el-dialog v-model="reviewVisible" title="评价本次合作" width="460"><el-form label-position="top"><el-form-item label="星级"><el-rate v-model="review.rating"/></el-form-item><el-form-item label="评价内容"><el-input v-model="review.content" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="reviewVisible=false">取消</el-button><el-button type="primary" @click="submitReview">提交评价</el-button></template></el-dialog></div></template>
